artifact.md_css:
.clm-msg.pc-md{white-space:normal;font-family:'Gelasio','Noto Color Emoji',Georgia,serif}
.pc-md p{margin:0 0 14px}
.pc-md h1{font-size:22px;line-height:30px;font-weight:700;margin:4px 0 12px}
.pc-md h2{font-size:18.5px;line-height:26px;font-weight:700;margin:18px 0 8px}
.pc-md h3{font-size:16.8px;line-height:24px;font-weight:700;margin:14px 0 6px}
.pc-md ul,.pc-md ol{margin:0 0 14px;padding-left:26px}
.pc-md li{margin:5px 0}
.pc-md li.pc-ind1{margin-left:22px}
.pc-md li.pc-ind2{margin-left:44px}
.pc-md strong{font-weight:700}
.pc-md code{font-family:'DejaVu Sans Mono',monospace;font-size:13.4px;background:rgba(255,255,255,0.07);border:1px solid var(--cl-border);border-radius:5px;padding:0 4px}
.pc-md pre{margin:0 0 14px;padding:14px 16px;border-radius:10px;background:#1a1a18;border:1px solid var(--cl-border);overflow:hidden;white-space:pre;font-family:'DejaVu Sans Mono',monospace;font-size:13px;line-height:20px;color:#e6e4dd}
.pc-md pre code{background:none;border:0;padding:0;font-size:inherit}
.pc-md hr{border:0;border-top:1px solid var(--cl-border);margin:16px 0}
.pc-md table{border-collapse:collapse;margin:0 0 14px;font-size:15px;line-height:21px}
.pc-md th,.pc-md td{border-bottom:1px solid var(--cl-border);padding:6px 14px 6px 0;text-align:left}
.pc-md th{font-weight:700}
.pc-md .pc-link{text-decoration:underline;text-underline-offset:3px}
.pc-artcard{display:flex;align-items:center;gap:14px;margin:4px 0 16px;padding:12px 16px;border:1px solid var(--cl-border);border-radius:12px;background:var(--cl-surface);font-family:Inter,sans-serif;width:360px}
.pc-artcard-ic{width:40px;height:40px;border-radius:8px;background:#1a1a18;border:1px solid var(--cl-border);display:flex;align-items:center;justify-content:center;color:var(--cl-muted);font-size:13px}
.pc-artcard-t{display:block;font-size:14px;line-height:20px;color:var(--cl-text);font-weight:500}
.pc-artcard-s{display:block;font-size:12px;line-height:16px;color:var(--cl-muted)}
